def fold_x(g):
    """A 180-symmetric X pattern (odd n x n) folded into ((n+1)//2)^2: main diagonal walks down-right, anti-diagonal walks down-left, meeting at the center."""
    n=len(g); m=(n+1)//2
    out=[[0]*m for _ in range(m)]
    main=[]; 
    for k in range(m-1): main += [(k,k),(k,k+1)]
    main.append((m-1,m-1))
    anti=[]
    for k in range(m-1): anti += [(k,m-1-k),(k+1,m-1-k)]
    anti.append((m-1,m-1))
    for k,(i,j) in enumerate(main): out[i][j]=g[k][k]
    for k,(i,j) in enumerate(anti):
        if (i,j)!=(m-1,m-1) or True:
            if not ((i,j)==(m-1,m-1) and k!=n//2): out[i][j]=g[k][n-1-k]
    return out
