def fold_x(g):
    """A 180-symmetric X pattern (odd n x n) folded into an ((n+1)//2)-square: each diagonal arm folds toward the center."""
    n=len(g); m=(n+1)//2
    out=[[0]*m for _ in range(m)]
    for d in range(n):
        if d < n//2:
            mi,mj,ai,aj = 0,d, d,m-1
        elif d == n//2:
            mi=mj=m//2; ai,aj=mi,mj
        else:
            e=n-1-d
            mi,mj,ai,aj = m-1,m-1-e, m-1-e,0
        out[mi][mj]=g[d][d]; out[ai][aj]=g[d][n-1-d]
    return out
